<?php
declare(strict_types=1);
require_once __DIR__.'/lib/helpers.php';send_cors_headers();$principal=require_principal(['customer','vendor','admin','influencer']);$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$unread=!isset($_GET['unread'])||$_GET['unread']!=='0';$stmt=$db->prepare('SELECT * FROM notifications WHERE recipient_type=:type AND recipient_id=:id AND (:unread=0 OR read_at IS NULL) ORDER BY created_at DESC LIMIT 100');$stmt->execute(['type'=>$principal['type'],'id'=>$principal['id'],'unread'=>$unread?1:0]);json_response(200,['success'=>true,'notifications'=>$stmt->fetchAll()]);}if($method==='PATCH'){$body=get_json_body();$id=trim((string)($body['id']??''));if($id==='all')$db->prepare('UPDATE notifications SET read_at=COALESCE(read_at,UTC_TIMESTAMP()) WHERE recipient_type=:type AND recipient_id=:owner')->execute(['type'=>$principal['type'],'owner'=>$principal['id']]);else $db->prepare('UPDATE notifications SET read_at=COALESCE(read_at,UTC_TIMESTAMP()) WHERE id=:id AND recipient_type=:type AND recipient_id=:owner')->execute(['id'=>$id,'type'=>$principal['type'],'owner'=>$principal['id']]);json_response(200,['success'=>true,'message'=>'Notification status updated.']);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
